<script setup>
import { onBeforeUnmount, ref } from 'vue';
const props=defineProps({items:{type:Array,required:true}}); const emit=defineEmits(['move','remove','select']); const board=ref(null); let drag=null;
const columns=Array.from({length:30},(_,i)=>i+1); const rows=['a','b','c','d','e','f','g','h','i','j'];
const pct=value=>value>100?value/10:value;
const pinLabel=item=>`${Math.max(1,Math.min(30,Math.round((pct(item.x)-7)/2.9)+1))}${rows[Math.max(0,Math.min(9,Math.round((pct(item.y)-24)/5.2)))]||'a'}`;
function start(event,item){event.preventDefault();const rect=board.value.getBoundingClientRect();drag={uid:item.uid,rect,dx:event.clientX-(rect.left+pct(item.x)*rect.width/100),dy:event.clientY-(rect.top+pct(item.y)*rect.height/100)};event.currentTarget.setPointerCapture?.(event.pointerId);document.addEventListener('pointermove',move);document.addEventListener('pointerup',stop);emit('select',item)}
function move(event){if(!drag)return;const rawX=(event.clientX-drag.rect.left-drag.dx)/drag.rect.width*100,rawY=(event.clientY-drag.rect.top-drag.dy)/drag.rect.height*100;const x=Math.max(7,Math.min(93,Math.round(rawX/2.9)*2.9));const y=Math.max(12,Math.min(88,Math.round(rawY/5.2)*5.2));emit('move',{uid:drag.uid,x,y,pin:`${Math.max(1,Math.min(30,Math.round((x-7)/2.9)+1))}${rows[Math.max(0,Math.min(9,Math.round((y-24)/5.2)))]||'a'}`})}
function stop(){drag=null;document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',stop)} onBeforeUnmount(stop);
</script>
<template><div class="interactive-board"><div ref="board" class="real-breadboard"><div class="power-bank top"><span class="rail positive">＋</span><span class="rail negative">−</span><div class="rail-holes"><i v-for="n in 30" :key="`t${n}`"></i></div></div><div class="terminal-labels"><span v-for="n in columns" :key="n">{{n}}</span></div><div class="terminal-grid upper"><template v-for="row in rows.slice(0,5)" :key="row"><i v-for="n in columns" :key="`${row}${n}`" :title="`${n}${row}`"></i></template></div><div class="center-trench"></div><div class="terminal-grid lower"><template v-for="row in rows.slice(5)" :key="row"><i v-for="n in columns" :key="`${row}${n}`" :title="`${n}${row}`"></i></template></div><div class="power-bank bottom"><span class="rail positive">＋</span><span class="rail negative">−</span><div class="rail-holes"><i v-for="n in 30" :key="`b${n}`"></i></div></div><button v-for="item in props.items" :key="item.uid" class="board-part" :class="`part-${item.id}`" :style="{left:`${pct(item.x)}%`,top:`${pct(item.y)}%`,'--part-color':item.color}" @pointerdown="start($event,item)" @dblclick="emit('remove',item.uid)"><span class="lead left"></span><strong>{{item.symbol}}</strong><small>{{item.name}}</small><span class="lead right"></span><em>{{pinLabel(item)}}</em></button></div><div class="board-hint">Arrastra: encaja al pin más cercano · doble clic: eliminar</div></div></template>
